    "judul": "APLIKASI PENGELOLAAN REKOMENDASI HASIL PEMERIKSAAN SATUAN PENGAWAS INTERNAL UNIVERSITAS SRIWIJAYA BERBASIS WEB",
    "abstrak": "The management of audit recommendation results at the Internal Supervisory Unit of Universitas Sriwijaya requires a system that can assist in recording, monitoring, document verification, and storing communication history in one system. This study aims to design and develop a web-based application to manage the follow-up of audit recommendation results. The data were collected through observation, interviews, and literature study. The application development used the Agile Framework with the Scrum approach and was implemented using Laravel, PHP, and MySQL with the Model-View-Controller pattern. This application provides several features, including a monitoring dashboard, recommendation management, follow-up management, file requests and responses, verification, comments, and data export. The results of Black Box Testing show that all features function properly.",
