    "judul": "SISTEM SINGLE SIGN-ON BERBASIS OAUTH 2.0 DAN ROLE-BASED ACCESS CONTROL PADA FAKULTAS ILMU KOMPUTER UNIVERSITAS SRIWIJAYA",
    "abstrak": "Information systems in the Faculty of Computer Science, Sriwijaya University generally have separate authentication and user management mechanisms in each application. This condition causes repeated login processes, decentralized role management, and less efficient application integration. This research aims to develop a role-based Single Sign-On (SSO) system as a centralized authentication and authorization service for applications within the Faculty of Computer Science, Sriwijaya University. The system was developed using a microservice approach consisting of Frontend SSO, Backend SSO, Backend Profile Service, and Docs SSO. Client application integration is implemented using the OAuth 2.0 Authorization Code Flow with PKCE, allowing client applications to redirect users to the SSO system, obtain tokens, and retrieve user data according to granted access rights. The development process was managed using Kanban through GitHub Projects, while testing was conducted using black box testing and integration testing. The results show that the developed system is able to provide centralized login, role and permission management, user profile services, integration documentation, and integration support for client applications such as SIKP, SIRPS, and a Laravel demo client.",
