    "judul": "PENGEMBANGAN APLIKASI RAWAT INAP PADA KLINIK SU’ADAH MENGGUNAKAN AGILE FRAMEWORK",
    "abstrak": "The inpatient service process at Su'adah Clinic is still not well integrated, causing delays in managing patient data, room arrangements, medical treatment records, supporting examinations, and payment processes. This study aims to design and develop a web-based inpatient application to support inpatient service management at Su'adah Clinic. The system development method used is Scrum within the Agile Framework with Unified Modeling Language (UML) modeling, including use case diagram, activity diagram, class diagram, and sequence diagram. The system was developed using the Laravel framework and MySQL database. System testing was conducted using the Black Box Testing method to ensure that system functions run according to user requirements. The results of this study show that the developed application can assist in managing patient data, room data, medical treatments, medication administration, laboratory and radiology examinations, ambulance services, and payment processes within one system. In addition, the application also helps organize data recording and inpatient service report preparation more systematically.",
