    "abstrak": "Risk management at the Internal Audit Unit of Universitas Sriwijaya is still conducted using separate, unintegrated tools, resulting in fragmented management, monitoring, assessment, and reporting activities. The objective of this research is to develop a risk management application for the SPI of Universitas Sriwijaya to enhance risk data management in an efficient, accurate, and structured manner. The benefits derived from this application include simplifying the risk data management process, reducing the risk of recording errors, streamlining report generation, and assisting leadership in decision-making. This research utilizes an Agile framework with the Scrum method, which involves several stages: vision, user stories, product backlog, sprint, daily standup, sprint review, and sprint retrospective, while the application testing employs black-box testing. The results of this study show that the developed system functions effectively, featuring integrated components including a dashboard, risk data management, clear access role distribution, and risk data export to Excel, which facilitates seamless report preparation.",
