    "id": "arc-mi-200",
    "no": 200,
    "judul": "APILIKASI MANAJEMEN KEHADIRAN BERBASIS ANDROID PADA PT PERTAMINA FUEL TERMINAL JAMBI",
    "abstrak": "PT Pertamina fuel terminal Jambi had the task of implementing operation petroleum by having certain to results of the welfare and prepared the people and the state, and meet the needs of fuel oil for domestic.So that companies engaged in oil would need an employee in a fair amount and should do the presence of effective and efficient management company to go well, however the presence in the company literally not good because the worn for doing absentee in the company previously experienced problems or obstacles in the system, and management presence in the company to do with manual, the purpose of the writer would like make apilikasi management based on android. The writer also use SDLC method of development, using android studio and room database as a database.",
