    "id": "arc-mi-257",
    "no": 257,
    "judul": "PENGEMBANGAN SISTEM ARSIP TUGAS AKHIR STIE AKUBANK MULIA DARMA PRATAMA",
    "abstrak": "This study focuses on the Final Project Archive system at Stie Akubank Mulia darma Pratama, the purpose of this research is to provide a means of Automating Final Project archiving management at Stie Akubank Mulia darma Pratama. The research method used in this report is by looking directly at the problems that are in place, analyzing the problems and thinking about solutions. The solution obtained from the problems that existed during the research was by creating an electronic application based on a simple Final Project Archive website that could be used to assist archiving at Stie Akubank Mulia Darma Pratama. By producing a website-based application that can be used at Stie Akubank Mulia Darma Pratama, this report can also be completed. Keywords : : Filing Management, Final Project",
