    "judul": "SISTEM INFORMASI PENJUALAN PADA TOKO PUTRA BERBASIS WEB",
    "abstrak": "This web-based sales information system is an information system that provides information from several processes including sales (accounting/management), stock (procurement), and reporting. So that a sales information system is needed at the Putra store. This information system aims to design a web-based sales information system to operate product data and transactions at the Putra store. The benefits of this information system are to make it easier for the Putra shop to operate and store transaction data, then the method used in this final project is the direct observation method to visit the Putra shop.",
