    "judul": "VIDEO COMPANY PROFILE BPSDMD PROVINSI SUMATERA SELATAN",
    "abstrak": "Company profile video is an electronic media to convey information that is effective in introducing a company or study program. The purpose of making this company profile video is as a visual information medium for BPSDMD South Sumatra Province. The benefit of making this company profile video is to make it easier for the public to know information about BPSDMD South Sumatra Province through video media. The method used in this company profile video is an interview with the head of the South Sumatra Province BPSDMD, where the South Sumatra Province BPSDMD requires visual information media so that it is easier for the public to find information on the South Sumatra Province BPSDMD. The result of the final project of this company profile video is 2 and a half minutes which can be utilized by BPSDMD of South Sumatra Province.",
