    "judul": "WEBSITE-BASED INVENTORY APPLICATION USING CODEIGNITER LA TANSA STORE",
    "abstrak": "The La Tansa shop is a business engaged in sales which is located on Jalan Ratu Sianum, District 3 Ilir, Palembang City. In the process of managing inventory at the La Tansa Store, they still use books and stationery, this results in frequent damage and loss of inventory data, then the process of checking and recording goods takes quite a long time. With this research, it is hoped that it can overcome the problems that occur and make it easier to manage inventory at the La Tansa Store. The software development method used is the waterfall method and is made using the PHP programming language by utilizing the CodeIgniter framework and MYSQL as a database.",
