    "id": "arc-mi-284",
    "no": 284,
    "judul": "PEMANFAATAN QUERY LIMIT AND ORDER PADA BASIS DATA APLIKASI POINT OF SALE (POS) BERBASIS ANDROID",
    "abstrak": "This final project aims to increase the effectiveness and efficiency of employee work process and to organize transaction’s data by utilizing query order and limit on database of an Android based Point of Sale system. This research was conducted at Rucca Street Coffee and Eatery. This research used waterfall software development life cycle. The system was developed using Android Studio software with Java programming language and Cloud Firestore database. The result of this research is a Point of Sale Application that can integrate all of cafe divisions. Utilization of query order and limit in the database that can sort and limit data output so that transaction data can be more organized.",
