    "judul": "PENERAPAN MYSQL EVENT SCHEDULER PADA APLIKASI SISTEM INFORMASI REKAM MEDIS BERBASIS WEB",
    "abstrak": "This final project focuses on designing and building a medical record information system website which aims to provide convenience for both nurses, doctors, and patients in carrying out the medical record process. In this study, the author uses the waterfall software method, CodeIgniter framework, PHP programming language, and conducts observations and interviews in collecting the data needed during research for the final project. The result of this final project is a web-based medical record information system application that implements the MySQL Event Scheduler feature which has the benefit of being able to schedule patient examinations and improve the performance of doctors and nurses to be more effective and efficient. Keywords : Applications, Websites, Medical Records, MySQL Event Scheduler",
