    "id": "arc-mi-287",
    "no": 287,
    "judul": "PEMBUATAN ANIMASI KARAKTER MENGGUNAKAN METODE PEN TOOLS SEBAGAI MEDIA PROMOSI DI MEDIA SOSIAL SMK PERTANIAN PEMBANGUNAN NEGERI SEMBAWA",
    "abstrak": "Making animated characters using pen tools method as a promotional media on social media at the Sembawa State Agricultural Development Vocational School is a promotional video that uses two-dimensional character animations that will explain everything from history to the facilities available at the school. This promotional video is disseminated on social media Facebook, Instagram, WhatsApp and Youtube. This promotional video aims to provide information about the school. The benefit of this promotional video is that it can be a reference for parents who want to send their children to the school. The method in making this promotional video is direct observation and interviews with the Public Relations and IT department of the school. And the results of this promotional video are 4 minutes 43 seconds.",
