    "judul": "APLIKASI PENJUALAN BERBASIS WEBSITE PADA TOKO ELY COLLECTION",
    "abstrak": "This final project was carried out with the aim of creating a website-based sales application for a songket shop called Ely Collection. The shop doesn't have an official website yet, the ordering process, payments are still done manually, so it takes a lot of time, effort and money. Based on these problems, the authors designed a web-based sales application using the PHP programming language and the CodeIgniter framework. The software development method used is the prototype method The benefits of this web-based sales application make it easier for consumers to view songket and order online, as well as help owners promote, manage and sell songket to consumers.",
