    "dosen_pa": "-",
    "pembimbing_1": "-",
    "prodi": "D3 Manajemen Informatika",
    "tahun_ta": "2021",
    "tahun_lulus": "2021",
    "tahun_angkatan": "2021",
    "link_repo_unsri": "http://repository.unsri.ac.id/52781/",
    "file_pdf_url": "http://repository.unsri.ac.id/52781/",
