    "no": 308,
    "judul": "APLIKASI WEB TRANSAKSI PADA OQODA LAUNDRY MENGGUNAKAN METODE WATERFALL",
    "abstrak": "This final project was carried out with the aim of creating an OQODA Laundry website application. In the laundry the recording process transactions made still not yet good. Based on problem required something system recording more transactions good for the recording process transaction can conducted with more good again from before. On implementation system project this use Code Igniter framework, method waterfalls and language programming PHP. So result from project this is a application transaction website on Oqoda Laundry that can be handle more transaction processing good again and the recording process more transactions short.",
