    "id": "arc-mi-309",
    "no": 309,
    "judul": "APLIKASI TUKAR SAMPAH BERBASIS ANDROID KELURAHAN BUKIT BARU PALEMBANG",
    "abstrak": "Bukit Baru Kelurahan still carries on the transportation of rubbish by way of house-to-house collection in the form of rubbish that is still mixed and in the selection process is still the responsibility of the garbage transporter. With the Android-based garbage exchange application, it is expected to simplify the process of sorting organic and non-organic and can make the citizens get financial benefits so that they are motivated and create a sense of caring for managing waste.",
