    "id": "arc-mi-314",
    "no": 314,
    "judul": "APLIKASI PELAPORAN KERUSAKAN FASILITAS PADA FAKULTAS ILMU KOMPUTER UNIVERSITAS SRIWIJAYA BERBASIS MOBILE WEB",
    "abstrak": "Computer Science Faculty of Sriwijaya University is one of many faculty in Sriwijaya University in Bukit and Indralaya Campus, this faculty have many facilities like laboratory, classroom and many more so there are also more damaged items in those facilities. Therefore Computer Science Faculty of Sriwijaya University need an application that helps the students to report these damaged facilities so there will be a replacement or repairmen as soon as possible. The system that will be built will use PHP as the programming language and MySQL as the database.",
