    "judul": "APLIKASI RENTAL MOBIL DAN MOTOR PADA UNO RENTAL BERBASIS WEB MOBILE",
    "abstrak": "Uno Rental Palembang is a car rental company located at 26 Ilir, Kec. Bukit Kecil, Palembang City, South Sumatra. Uno rental does not yet have an application that can facilitate the car rental process. In order to make it easier in the process of renting cars and motorbikes, so we need a web-based car and motorbike rental application that can make it easier for admins and customers in carrying out car and motorcycle rental transaction activities.",
