    "abstrak": "In this study, the aim of this research is to create an animated learning video. At SMK IT MUTIARA AZZAM PALEMBANG. Where during this pandemic, learning and teaching activities were hindered, one of them was practicum. So we need a system that can help the learning system. In order to make the teaching and learning process easier. With the animation of learning videos for making LAN networks, it is hoped that it can help students understand the concept of LAN networks and make LAN Network Cables more easily and then practice them directly and help teachers in delivering material to students from the Learning Video",
