    "abstrak": "The Palembang City Archives and Library Service is a regional work unit that carries out the tasks of the Palembang City Government, especially in the field of archives and libraries which involve coaching, structuring, managing archives, libraries and documentation of government, private, BUMD and community agencies within the Palembang City Government So the purpose of the study is to develop an application to help store conventiona.l archive data, to minimize the occurrence of archive damage at the South Sumatra Pmvincial Archives Service t,ased on a mohile website.",
