    "id": "arc-mi-341",
    "no": 341,
    "judul": "SISTEM INFORMASI PERSEDIAAN BARANG PADA TOKO 3R BERBASIS WEB",
    "abstrak": "Inventory information System is a sales information system that produces a variety of information that can be useful to supportactivities sales. Based on surveys and interviews with the owner of the 3R store, information was obtained that the system usde in the existing 3R Shop is still manual. Therefore 3R Stores need a new method to manage and record various transactions in and out of goods. This system information was built with the hope that it can help record data in and out of goods on a web-based 3R Store, so as to increase work effectiveness and provide information quickly and accurately. The system to be created is a mobile web-based information system. Using the PHP programming language and MySQL as the database. Keywords: Information Systems, inventory, PHP, MySQL,Mobile Web",
