    "abstrak": "Video Animation Media Learning Know The Five Human Senses For Kindergarten Students to make it easier for students to understand learning materials about the five human senses. In the making of this learning media animation video using the preparation in the form of observation and storyboard making. With this video animation learning media can help in teaching and providing understanding to students and can help teachers in carrying out the learning process.",
