    "judul": "APLIKASI AYO BELAJAR PADA SMAN 1 GELUMBANG BERBASIS WEB MOBILE",
    "abstrak": "In this study, the aim is to make learning applications. At high school 1 Gelumbang does not have an internal school application for learning. So we need a system that can help the learning system. In order to make the teaching and learning process easier. With the Ayo Belajar application proposed at high school 1 Gelumbang, it is able to produce fast and archived information so that it makes it easier to manage student and teacher data. With this application, it is hoped that it will make it easier for students to learn and make it easier for teachers to deliver learning material.",
