    "judul": "APLIKASI KASIR LAUNDRY BERBASIS WEB PADA RUMAH LAUNDRY INDRALAYA",
    "abstrak": "The Informatics Management Study Program is one of the study programs at the Faculty of Computer Science, especially at Sriwijaya University, this study program focuses on management, information and communication science, this study program can also help many jobs such as the Web-Based Laundry Cashier Application, this application can make it easier for owners to store data on customers who wash clothes and customers who have taken clothes. The data used is the Web-based Laundry Cashier Application using Java as the programming language and Mysql as the DBMS. Keywords: Web-based Laundry Cashier Application, Java, Mysql",
