    "judul": "SISTEM INFORMASI PENGARSIPAN SURAT PADA PEMERINTAH KABUPATEN OGAN KOMERING ULU TIMUR INSPEKTORAT DAERAH MARTAPURA",
    "abstrak": "Sistem Informasi Pengarsipan Surat Pada Dinas Pemerintah Kabupaten Ogan Komering Ulu Timur Inspektorat Daerah Martapura adalah sebuah sistem berbasis website yang berfungsi untuk mengarsipkan surat masuk maupun keluar di Inspektorat Daerah Martapura. Aplikasi ini dapat menyimpan dokumen surat dalam bentuk foto. Aplikasi dibuat karena Inspektorat Martapura belum menggunakan sistem yang terkomputerisasi dalam kegiatan pengarsipan surat. Adapun hasil akhir dari pembuatan website ini ialah dapat melakukan pengarsipan surat yang terkomputerisasi agar mempermudah pengarsipan dan pencarian kembali surat yang sudah diarsipkan. Pembuatan program ini menggunakan bahasa Hypertext Prepocessor (PHP).",
