    "judul": "SISTEM INFORMASI PENGOLAHAN DATA PERPUSTAKAAN PADA KANTOR PERPUSTAKAAN, DOKUMENTASI DAN ARSIP DAERAH KOTA PRABUMULIH",
    "abstrak": "Curently, Library Data Processing in the library, Documentation and Archives Office of Prabumulih is still done manually, starting from data collection of members, books, lending transactions to the presentation of library data reports. Data processing like this quite complicated, causing a buildup of books in the arsip cabinet. Data Processing Information System in the office of Library, Documention and Regional Archives of Prabumulih City, Library Data Processing Information System in the Library, Documentation and Archive Office of Prabumulih City, PHP programming language and MySQL database.",
