    "abstrak": "PT. Tania Selatan Kebun Bambu Kuning is a CPO Commodity incorporated in the Oil Feed industry group. In managing data in and out, still using paper bills. The purpose of this study is to build Management Data Applications for incoming and outgoing goods using the waterfall method. This application contains features that help employees in performing their duties, can add item data, add data categories, add data suppliers, add incoming items, add items out and search for data.",
