    "id": "arc-mi-358",
    "no": 358,
    "judul": "APLIKASI LAYANAN PERBAIKAN KENDARAAN BERMOTOR PADA BENGKEL BERBASIS WEB",
    "abstrak": "Application of Motor Vehicle Repair Services in Web-Based Workshop is a web- based system that has the function of being able to register for customers who will do vehicle repairs. The existence of making this application is due to the motor lan service workshop still registering with a simple process and not using existing technology. The author uses the method of collecting data obtained through field studies namely by observation, interviews and documentation to design the software application, the author uses the waterfall development method, in solving the problems above, then a Motor Vehicle Repair Service Application is built on the web-based Workshop. This application uses the PHP programming language, uses the Sublime Text 3 editor and uses the Mysql database. The results obtained from making this application are easier for customers in registering motor vehicle repairs and make it easier for administrators to search the history of motorcycle repairs done by the customer",
