    "id": "arc-mi-359",
    "no": 359,
    "judul": "APLIKASI SURAT PERINTAH PERJALANAN DINAS PT. BUKIT ASAM TBK BERBASIS WEB",
    "abstrak": "PT. Bukit Asam Tbk is one of the state-owned companies engaged in coal mining. The production of the Tanjung Enim mining coal unit is not only marketed in Tanjung Enim but also to others areas. And the International Market through Bandar Lampung Tarahan Port and Dermaga Kertapati. Because employees often do official trips with drivers outside the Palembang area., especially to Tanjung Enim. PTBA Dermaga Kertapati unit records the driver’s official travel using a notebook, so it requires considerable time in reporting and searching data. In this research, a Travel Office Service Letter Application of PT. Bukit Asam Tbk Web-based to help manage data on official travel and print official letters. The method used in application development is the waterfall method., the application design is implemented into the PHP programming language by using MySQL as a DBMS. Kerywords: Official Travel, Driver, Official Letter",
