    "abstrak": "The Office Kecamatan Tugumulyo Kabupaten Musi Rawas is government agencies that have used a computerized system in carrying out their activities are included in the processing of personnel data. But there are limited acces to data on personnel data that requires a relatively long time in searching and receiving data. By looking at the problem, a website based information system is needed. Website information system develops along with the rapid development of internet technology can help in the ease and speed of sending, delivering and receiving data. The purpose of this study is to develop employee performance data processing applications using the waterfall method. This application can help admin in making employee data reports, SK work employee data, employee performance data and employee penalty data.",
