    "judul": "APLIKASI PENGOLAHAN DATA NILAI SISWA PADA SD NEGERI 1 TULUNG HARAPAN KEC. LEMPUING KAB. OKI BERBASIS WEB",
    "abstrak": "Student Value Data Processing Application at SD Negeri 1 Tulung Harapan Kec. Lempuing Kab. OKI in the Web-based is an application that processes value data of students at SD Negeri 1 Tulung Harapan Kec. Lempuing Kab. OKI. This application was made because the data processing of students in elementary school is still using the manual method that is recap or write the value data by hand writing and stored in the book. And the end result of this application is that it can make it easier for teachers and admins to process value data of students and that will be stored in the database and will facilitate the process of data recapitulation.",
