    "id": "arc-mi-366",
    "no": 366,
    "judul": "APLIKASI PENGELOLAAN DATA PEGAWAI PADA DINAS PENDIDIKAN KABUPATEN LAHAT",
    "abstrak": "The Lahat Regency Education Office is a government agency that has used a computerized system to carry out its activities including in the processing of staffing data. However there are limited data access on staffing data which requires a relatively long time in searching and receiving data. The purpose of this research is to develop the Employee Data Processing Application collected through observation, interview and literature study. The system is in the form of web and PHP programming language and MySQL database. This application can help the admin in making employee data reports, Position data and employee training data. Keywords: Employee, Data Collection, Application Program, PHP, MySQL.",
