    "abstrak": "The Computer Engineering and Computer Engineering Study Program is one of the study programs in the Faculty of Computer Science, Sriwijaya University. This study program focuses on the field of informatics, this study program requires the existence of Web Profile Information System to accommodate the computer engineering and engineering study programs and techniques network computers, this web profile can also be used as a medium of information for students of computer engineering study programs and network computer engineering. The data used in the design of a Web Profile Information System uses PHP as programming language, micromedia dreamweaver as an editor and MySql as DBMS.",
