    "id": "arc-mi-374",
    "no": 374,
    "judul": "APLIKASI KUESIONER UNTUK ALUMNI BERBASIS ANDROID DI PROGRAM STUDI MANAJEMEN INFORMATIKA FAKULTAS ILMU KOMPUTER UNIVERSITAS SRIWIJAYA",
    "abstrak": "Alumni are an important element in determining the quality of educational institutions, thus requiring a modem and systemic organi:zation. An alumni portal application is a media that can be used for communication media between alumni, giving questions to alumni and seeking information about current alumni. With the application of questionnaires for alumni designed by the author using the android studio application programming language and MySQL Database, it can facilitate alumni to get alumni information, information about the current alumni presence and become a communication media to strengthen ties between students and alumni.",
